mapper.select:
SELECT land.*, land_type.type_name AS type_name, land_type.description AS type_description, user_a.username AS customerA_username, user_a.phone AS customerA_phone, user_b.username AS employee_username, user_b.phone AS employee_phone FROM land INNER JOIN land_type ON land.land_type = land_type.id INNER JOIN user AS user_a ON land.a_id = user_a.id INNER JOIN user AS user_b ON land.employee_id = user_b.id
AND land.status = #{land.status}
AND land.address LIKE CONCAT('%', #{land.address}, '%')
AND land.land_type = #{land.landType}
AND land.land_name LIKE CONCAT('%', #{land.landName}, '%')
AND land.id = #{land.id}
AND land.a_id = #{land.aId}
AND land.area >= #{land.area}
ORDER BY price
ORDER BY area
ORDER BY id
